SELECT SCREEN_LAYOUT_XML_TEXT AS CONTENT
  FROM LGCOM_USER_SCREEN_LAYOUT_N
 WHERE APPLICATION_USER_ID = #{USER_SESSION.applicationUserId}
   AND PROGRAM_ID = #{programId}
   AND SCREEN_GRID_NAME = #{componentId}

SELECT COUNT(PROGRAM_ID) AS CONFIG_COUNT
  FROM LGCOM_USER_SCREEN_LAYOUT_N
 WHERE APPLICATION_USER_ID = #{USER_SESSION.applicationUserId}
   AND PROGRAM_ID = #{programId}
   AND SCREEN_GRID_NAME = #{componentId}

mapper.update:
UPDATE LGCOM_USER_SCREEN_LAYOUT_N
   SET SCREEN_LAYOUT_XML_TEXT = #{screenLayout}
 WHERE APPLICATION_USER_ID = #{USER_SESSION.applicationUserId}
   AND PROGRAM_ID = #{programId}
   AND SCREEN_GRID_NAME = #{componentId}

