   WHERE APPLICATION_USER_ID = #{USER_SESSION.applicationUserId}
     AND INQUIRY_CONDITION_VALUE = #{keyword}
     AND EFFECTIVE_TO_DATE > SYSDATE
ORDER BY LOG_SEQ_NO

